<?php $year = (int) current_time( 'Y' ); $months = array_fill( 1, 12, 0 ); $month_names = array( 1 => 'Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic' ); $total_visits = 0; foreach ( $customers as $customer ) { foreach ( (array) ( $customer['visits'] ?? array( $customer['date'] ) ) as $visit ) { if ( (int) substr( $visit, 0, 4 ) === $year ) { $month = (int) substr( $visit, 5, 2 ); if ( isset( $months[ $month ] ) ) { $months[ $month ]++; $total_visits++; } } } } $max_visits = max( 1, max( $months ) ); ?>
<div id="lw-activity-panel" class="lw-settings-panel" role="tabpanel" aria-labelledby="lw-activity-tab" hidden>
	<div class="lw-activity-header"><div><h2>Actividad de visitas</h2><p>Visitas de clientes durante <?php echo esc_html( $year ); ?>.</p></div><div class="lw-activity-total"><small>Total de visitas este año</small><strong><?php echo esc_html( $total_visits ); ?></strong></div></div>
	<div class="lw-month-chart"><?php foreach ( $months as $month => $count ) : ?><div><span class="lw-month-value"><?php echo esc_html( $count ); ?></span><i style="height:<?php echo esc_attr( max( 4, round( ( $count / $max_visits ) * 100 ) ) ); ?>%"></i><small><?php echo esc_html( $month_names[ $month ] ); ?></small></div><?php endforeach; ?></div>
</div>
